          scenario: "本日は米SOX8%高を受けたガラス・電子材料関連への買いで+3.76%まで上昇して引けたが、その直後の開示で通期予想が大幅に切り下げられた。下方修正の理由は米国子会社の工場生産停止・譲渡という複合材事業の構造改革、ディスプレイ事業の需要減と定期修繕費増、原燃料高であり、一過性の特損だけでなく本業の営業利益が330→200億円へ4割近く削られている点が重い。会社計算では下期経常が前年同期比-63.0%となる。日中に材料と逆方向へ買われていたぶん、その分の巻き戻しが出やすい、というのが基本シナリオ。【朝更新】前提だった「7/31夜の米半導体株が続伸してセクター全体に押し上げられる」というリスクは、SOX指数が+0.07%とほぼ横ばいで終わり、マイクロンが単日-5.90%と弱かったことでやや後退した。加えてCME日経先物が大阪比-450円で引けており、指数そのものが金曜の急騰分を戻す方向で始まる公算が大きい。前日夕方の見立てより条件は整っている。",
