      outlook: "【7/31朝7時更新】寄り付きは先物の大幅高と急激な円高が真正面からぶつかる形になる。CME・大阪の先物は63,670円(+1,960円)と現物比約1,800円のプレミアムで、SOX指数+8.19%を受けて半導体関連には強い追い風が吹く一方、ドル円は163円53銭から159円54銭へ約4円の円高で、輸出・海外収益比率の高い銘柄には明確な逆風となる。指数だけを見て強気になれる場面ではなく、『先物に引っ張られて高く寄った後、円高を理由に売られる』という寄り天パターンには特に注意したい。加えて8:30に東京都区部CPI(予想+1.8%)と完全失業率、8:50に鉱工業生産・小売売上高が発表され、寄り前に材料が追加される。以下は前日夕方時点の見通し。明日7/31(金)の最大のイベントは日銀金融政策決定会合の結果公表と植田総裁会見(15:30予定)で、政策金利1.00%据え置きが中心シナリオとされる。焦点は同時公表の展望レポートと、会見での今後の利上げペースに関する文言であり、ここで為替と金利が振れると内需・金融の物色が一気に入れ替わる可能性がある。国内では東京都区部CPI・鉱工業生産の発表があり、決算はキオクシア、村田製作所など281社と本日の135社をさらに上回る集中日となるため、個別のボラティリティは高くなりやすい。米国では31日の取引終了後にアップルとアマゾンの決算が控えており、週明けのハイテク・半導体の方向感を左右する。本日の日経平均は前場高値から1,000円以上下押しして引けており上値の重さが残る一方、TOPIXの逆行安と値下がり銘柄優勢が示す通り物色は半導体の好決算銘柄に偏っている。月末の需給要因も絡み、日銀会合と大型決算という2つのリスクを前にポジションを傾けにくい地合いが想定される。なお朝時点で夜間にすでに4円の円高が進んだことで、日銀会合の結果が『円高をさらに加速させる方向』に出た場合のインパクトは前日夕方に想定していたより大きくなっている点に留意したい。",
