            detail: "7/29 15:30に業績修正(IFRS)を発表。27年3月期上期の最終利益は従来予想159億円→246億円(前年同期171億円)で+43.2%の増益見通し、通期は営業益605億円→655億円(+8.3%)、最終420億円→507億円(+20.7%)へ増額。1株益は388.37円→475.47円、配当は前期112円→今期134円。【朝7:00更新の重要な訂正】会社の修正理由は米Pentagon Technologies Group社の株式譲渡(5/13決定・6/30完了)であり、連結除外時の在外営業活動体換算差額振替による『その他の収益』約50億円＋株式売却益・リース解約清算益による『非継続事業からの利益』37億円＝計約87億円の押し上げ。売上高予想は据え置きで、本業改善による修正ではない。夜間PTSは8,292.5円(+1.40%)にとどまり最終約定が7/29 17:10で止まっており、市場はほぼ評価していない。株探7/30朝の『本日注目すべき好決算銘柄』にも採用されていない。X上でも一過性要因である点が指摘されている(@IGoldeneggs 昨日15:39)。この訂正を受けてプランを買いから見送りに変更した。",
            sources: [{ label: "株探 決算速報", url: "https://kabutan.jp/news/?b=k202607290041" }, { label: "【朝更新】適時開示 子会社株式譲渡に伴う収益計上と業績予想の修正", url: "https://kabutan.jp/disclosures/pdf/20260729/140120260728501036/" }]
