          scenario: "1Q売上3,466億円(+32.8%)、営業利益1,871億円(+44.7%)、経常1,968億円(+49.6%)、最終益1,391億円(+51.0%)と全項目で大幅増益。営業利益率が49.5%から54.0%へ改善しており収益性の質も伴う。当日は半導体関連の全面安に巻き込まれて-4.34%で引けたため決算は株価に織り込まれておらず、【朝更新】夜間PTSでは76,800円(+8.25%)まで買われている(ただしPTS出来高は3,500株と薄く、朝の気配で要再確認)。7/29はギャップアップ寄りが想定され、初動の勢いより寄った後に値を保てるかが焦点になるのが基本シナリオ。売買代金591.9億円と板が厚く、成行の滑りが小さい点はこの地合いでは相対的な利点。",
